1	// site-stats — recount the canon and land the four numbers the site promotes.
2	//
3	// The whole run is deterministic: clone the canon the site names, count, substitute,
4	// deliver. Nothing here is a judgment call, which is why the task runs no agent.
5	//
6	// Idempotence is the property that keeps this quiet: the counts are a pure function
7	// of the canon at HEAD, and they are compared against the BASE TIP's copy of the file
8	// rather than the working tree, so a week in which the canon gained nothing countable
9	// opens no PR at all.
10	
11	import { execFileSync } from 'node:child_process';
12	import { mkdtempSync, rmSync } from 'node:fs';
13	import { tmpdir } from 'node:os';
14	import { join } from 'node:path';
15	import { pathToFileURL } from 'node:url';
16	// The long reach into the mount is deliberate, and file-placement flags it as such.
17	// Landing a PR under a member's delivery settings is claudinite-tasks' to own — it
18	// is the same library the canon's own agentless tasks call — and a local copy of it
19	// here would be a second implementation of the one thing that must not have two.
20	import { deliverGenerated, baseTip, readAt, remoteUrl } from '../../../../../shared/packs/claudinite-tasks/deliver-generated.mjs';
21	import { countCanonStats } from './count-canon-stats.mjs';
22	import { applyStats, canonRepoUrl, STAT_LABELS } from './promoted-stats.mjs';
23	
24	const PROMOTED_PATH = 'site/data/promoted.js';
25	const PR_BRANCH_PREFIX = 'claudinite/site-stats';
26	
27	const log = (m) => console.log(`site-stats: ${m}`);
28	
29	const git = (cwd, args) => execFileSync('git', ['-C', cwd, ...args], {
30	  encoding: 'utf8',
31	  maxBuffer: 64 * 1024 * 1024,
32	});
33	
34	// A shallow single-branch clone of the canon: history and tags carry nothing this
35	// count reads, and the tree alone is an order of magnitude smaller than the repo.
36	function cloneCanon(url) {
37	  const dir = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
38	  execFileSync('git', ['clone', '--depth', '1', '--single-branch', '--no-tags', '--quiet', url, dir], {
39	    encoding: 'utf8', maxBuffer: 64 * 1024 * 1024,
40	  });
41	  return dir;
42	}
43	
44	// Everything under `packs/`, read from the tree rather than walked on disk — the
45	// same listing shape `countCanonStats` takes from a fixture.
46	const packPaths = (dir) => git(dir, ['ls-tree', '-r', '--name-only', 'HEAD', '--', 'packs'])
47	  .split('\n').filter(Boolean);
48	
49	const showOrNull = (dir, path) => {
50	  try { return git(dir, ['show', `HEAD:${path}`]); } catch { return null; }
51	};
52	
53	export async function main() {
54	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
55	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
56	  const token = process.env.GITHUB_TOKEN;
57	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
58	  if (!repo) throw new Error('CLAUDINITE_REPO / GITHUB_REPOSITORY is not set (owner/repo)');
59	  if (!token) throw new Error('GITHUB_TOKEN is not set — the recount cannot read the base or deliver its PR');
60	
61	  const baseSha = baseTip(root, remoteUrl(repo, token), base);
62	  const promoted = readAt(root, baseSha, PROMOTED_PATH);
63	  if (promoted === null) {
64	    console.error(`claudinite-needs-human: decision — ${PROMOTED_PATH} does not exist on ${base}; the page this task maintains has moved or gone`);
65	    throw new Error(`${PROMOTED_PATH} is absent from ${base}`);
66	  }
67	
68	  // The site names its own canon, so the address lives in one place and this task
69	  // follows it rather than carrying a second copy.
70	  const canonUrl = canonRepoUrl(promoted);
71	  if (!canonUrl) {
72	    console.error(`claudinite-needs-human: decision — ${PROMOTED_PATH} no longer declares a canonRepo, so there is nothing to count`);
73	    throw new Error(`no canonRepo in ${PROMOTED_PATH}`);
74	  }
75	
76	  let canon;
77	  try {
78	    canon = cloneCanon(`${canonUrl.replace(/\.git$/, '')}.git`);
79	    const directory = showOrNull(canon, 'packs/directory.GENERATED.md');
80	    if (!directory) throw new Error('the canon carries no packs/directory.GENERATED.md');
81	    const paths = packPaths(canon);
82	    const counts = countCanonStats({
83	      directory,
84	      readme: (pack) => showOrNull(canon, `packs/${pack}/README.md`),
85	      paths,
86	    });
87	
88	    const { text, changed, missing } = applyStats(promoted, counts);
89	    if (missing.length) {
90	      console.error('claudinite-needs-human: decision — '
91	        + `${PROMOTED_PATH} no longer carries a stat labelled ${missing.map((l) => `"${l}"`).join(', ')}; `
92	        + 'decide whether this task should still maintain the block someone rewrote');
93	      throw new Error(`stat label(s) missing: ${missing.join(', ')}`);
94	    }
95	
96	    log(`counted ${counts.packs} packs, ${counts.checks} checks, ${counts.skills} skills, ${counts.tasks} tasks`);
97	    if (!changed) {
98	      log('the page already states all four — nothing to deliver');
99	      return;
100	    }
101	
102	    const moved = Object.entries(STAT_LABELS)
103	      .map(([key, label]) => `- **${counts[key]}** ${label}`).join('\n');
104	    const pr = await deliverGenerated({
105	      root, repo, base, token, log,
106	      stamp: new Date().toISOString().slice(0, 10),
107	      branchPrefix: PR_BRANCH_PREFIX,
108	      files: { [PROMOTED_PATH]: text },
109	      message: 'site: recount the canon-wide stats',
110	      title: 'site: recount the canon-wide stats',
111	      body: [
112	        `Recounted the four canon-wide figures in \`${PROMOTED_PATH}\` against`,
113	        `${canonUrl} at its current head:`,
114	        '',
115	        moved,
116	        '',
