// Is this run's diff NARROW — small enough that the asker said, up front, they did
// not want to be asked (tasks-dispatch DESIGN §16.11)? The request task's ceiling
// allows a merge; THIS is what decides whether one happens, so the call is
// arithmetic over the diff rather than the session's opinion of its own work.
//
// Narrow means every changed file is one of:
//   - documentation — a Markdown/text file;
//   - a test — a file or directory the repo names as one;
//   - comments only — the code either side of the change is identical once the
//     comments are stripped;
//   - code, in at most ONE directory across the whole diff.
//
// So a change that edits one module, its tests, a README and a comment in a file
// somewhere else is narrow; one that edits code in two directories is not.
//
// THE LIMIT THAT BOUNDS THE VERDICT: a file `commentOnly` cannot answer for counts
// as code, so a comment-only edit in a language the parser does not model parks the
// run rather than merging it. That is the safe end, and it is deliberate — the
// verdict grants a merge nobody will look at.

import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { COMMENT_CHECKABLE, commentOnly } from '../../../../../engine/checks/helpers/code-scanning.mjs';

// Re-exported so this module stays the one place a caller asks about a narrow
// diff; the parser and the safe end are the shared helper's.
export { COMMENT_CHECKABLE, commentOnly };

const DOC_EXTENSIONS = new Set(['.md', '.markdown', '.txt', '.rst']);

const TEST_DIRS = new Set(['test', 'tests', '__tests__', 'spec', 'specs', 'fixtures', 'testdata']);

// A path's kind, from the path alone: 'doc', 'test', or 'code'. Directory names
// are matched on whole segments (`tests/`), never on substrings, so `latest/` is
// not a test directory; file names are matched on the conventions every ecosystem
// here shares.
export function classifyPath(file) {
  const segments = file.split('/');
  const name = segments[segments.length - 1];
  if (segments.slice(0, -1).some((seg) => TEST_DIRS.has(seg) || seg.endsWith('-tests') || seg.endsWith('_tests'))) return 'test';
  if (/(^|[.\-_])(test|tests|spec)[.\-_]/i.test(name) || /^test_/i.test(name)) return 'test';
  if (DOC_EXTENSIONS.has(path.extname(name).toLowerCase())) return 'doc';
  return 'code';
}

// The verdict over a whole diff. `entries` are `{ file, before, after }`, contents
// null where the file was added or deleted. Returns the verdict and the WHY —
// which files forced it — because a run that parks has to say what it parked over.
export function narrowVerdict(entries) {
  const codeDirs = new Map();
  const kinds = [];
  for (const { file, before, after } of entries) {
    const kind = classifyPath(file);
    if (kind !== 'code') { kinds.push({ file, kind }); continue; }
    if (commentOnly(file, before, after)) { kinds.push({ file, kind: 'comments' }); continue; }
    const dir = path.dirname(file);
    if (!codeDirs.has(dir)) codeDirs.set(dir, []);
    codeDirs.get(dir).push(file);
    kinds.push({ file, kind: 'code' });
  }
  const dirs = [...codeDirs.keys()].sort();
  return {
    narrow: dirs.length <= 1,
    codeDirs: dirs,
    files: kinds,
    why: dirs.length <= 1
      ? (dirs.length === 0
        ? 'no code changed — documentation, tests and comments only'
        : `code changed in one directory (${dirs[0]}), beside documentation, tests and comment-only edits`)
      : `code changed in ${dirs.length} directories: ${dirs.join(', ')}`,
  };
}

// --- the CLI ------------------------------------------------------------------

// `stderr: ignore` because the ONE expected failure here — `git show` on a path
// that does not exist at that ref — is how an added or deleted file answers, and
// letting git narrate it once per such file buries the verdict the caller reads.
const git = (args, cwd) => execFileSync('git', args, {
  cwd, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, stdio: ['ignore', 'pipe', 'ignore'],
});

// The content of `file` at `ref`, or null when it does not exist there (an added
// file) — the same answer a deleted file's "after" gets.
function contentAt(ref, file, cwd) {
  try {
    return git(['show', `${ref}:${file}`], cwd);
  } catch {
    return null;
  }
}

// The diff this branch carries against `base`, read from the merge base so
// commits that landed on the base meanwhile are not counted as this run's work.
export function diffEntries({ base, cwd = process.cwd() }) {
  // The checkouts these runs work in are shallow, where `merge-base` has no common
  // ancestor to find; the base ref itself is then the honest comparison point.
  let mergeBase;
  try {
    mergeBase = git(['merge-base', base, 'HEAD'], cwd).trim();
  } catch {
    mergeBase = base;
  }
  const names = git(['diff', '--name-only', mergeBase, 'HEAD'], cwd).split('\n').map((l) => l.trim()).filter(Boolean);
  return names.map((file) => ({
    file,
    before: contentAt(mergeBase, file, cwd),
    after: contentAt('HEAD', file, cwd),
  }));
}

async function main() {
  const argv = process.argv.slice(2);
  const at = (flag) => (argv.includes(flag) ? argv[argv.indexOf(flag) + 1] : null);
  const cwd = at('--root') ?? process.env.CLAUDE_PROJECT_DIR ?? process.cwd();
  const base = at('--base') ?? 'origin/main';

  const entries = diffEntries({ base, cwd });
  if (entries.length === 0) {
    console.log('NARROW: no — this branch changes nothing against the base');
    return;
  }
  const verdict = narrowVerdict(entries);
  for (const { file, kind } of verdict.files) console.log(`  ${kind.padEnd(8)} ${file}`);
  console.log(`\nNARROW: ${verdict.narrow ? 'yes' : 'no'} — ${verdict.why}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((e) => { console.error(`narrow-diff: ${e.message}`); process.exitCode = 1; });
}

// The repo tidy-up, as a composable pack: the PR/issue sweep and the comment pass
// the repo's own scheduler runs, contributed the same way any pack contributes checks and skills.
// Declaring tidy-repo puts its scheduled task on that repo's schedule; removing it
// is a durable opt-out (baselining never re-adds it — see the tidy-repo-seed
// migration).
//
// A declared pack (no detect fingerprint): --init seeds it into every new repo's
// declaration, and the one-time tidy-repo-seed migration seeds the existing fleet.
// It carries no conformance checks — its work is the scheduled tasks — but the
// improve-comments skill owns the gate that bounds the one task writing the source.
//
// One task per dimension — tidy-issues (daily, acts), tidy-prs (weekly,
// assess-only), improve-comments (weekly, acts on the source) — each delegating its
// verdict to a skill of its own, and the two GitHub-object ones reconciling their
// OWN standing tracker. Narrow tasks, not one wide one: each has its own trigger and
// scope, none depends on another's result, so there is no ordering barrier and a
// dimension with nothing to do stays silent.
export default {
  version: '60827.2',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'housekeeping of one repo — triage verdicts over its issues and pull requests, the comments in its source, standing trackers',
    excludes: 'extracting lessons into packs — that is claudinite-growth; cross-repo fleet sweeps are claudinite-fleet-sheepdog',
  },
  seededByDefault: true,
  // The pack's scheduled tasks live in this pack's own `tasks/<id>/`, discovered by
  // the scheduler's filesystem scan (packs/claudinite-tasks/discover.mjs), not declared here.
  //
  // The worker skills those tasks apply live under this pack's own skills/ and mount
  // wherever tidy-repo is declared; improve-comments' also carries the check that
  // bounds its task's write surface.
};

// tidy-repo task: improve-comments — the one tidy dimension whose subject is the
// repo's own source rather than its GitHub objects. The other three assess or act
// on issues, PRs and branches; this one reads a slice of the code AS COMMENTS and
// fixes what it finds there. Worker: task.md, which runs the improve-comments skill
// and nothing else.
//
// WHY IT IS A TASK AT ALL: a comment decays as the code around it changes and
// nothing makes it fail. No test goes red, no check fires, and no session working on
// something else will stop to fix one. The only way a repo's comments get read as
// comments is a pass whose whole job that is.
//
// WEEKLY. Comment drift is not latency-sensitive — a stale comment costs the next
// reader, whenever that is — and the window's commits are what name the files whose
// comments are likeliest wrong, so a weekly window is a bigger and better-targeted
// scope than a daily one for the same session cost.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The pinned commit subject the run's own scope gate keys on, stated in task.md and
// enforced by the skill's `improve-comments-scope` check. Kept in step by the
// declaration test beside this pack's other tests.
const RUN_TITLE = 'Claudinite tidy: improve comments';

// How many of the window's changed files one round reads. A busy week can touch
// hundreds, and a session handed all of them skims; the rest are next round's, and
// the run says so rather than presenting a truncated list as the whole window.
const MAX_FILES = 40;

export default {
  id: 'improve-comments',
  frequency: 'weekly',                   // the weekly anchor (DESIGN §2); the window's commits are the scope
  precondition_signals: ['commits', 'prs'],
  agent_model: 'opus',                   // whether a comment carries a why the code cannot state is the judgment here, and a wrong call lands in the repo's source
  // Reviewed, never landed unattended. The scope check proves the diff is
  // comment-only, which is what makes the pass SAFE — it does not make the comments
  // themselves right, and a confidently wrong comment is the exact failure this task
  // exists to remove. A repo that wants these to land without review says so by
  // raising the ceiling here, in one line.
  expected_outcome: 'open-pr',
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,

  // Two gates, in order. Did anything land in the window — comments decay against
  // code, so a quiet week has nothing to re-read. Then: is this pass's previous PR
  // still open, in which case a second one would stack an unreviewed comment sweep
  // on an unreviewed comment sweep, over files the first one may already have
  // touched. Reading the pending PR's TITLE rather than a marker on the item means
  // a PR the owner opened by hand from this branch gates the round too.
  precondition(signals) {
    const openPrs = signals.prs?.open ?? [];
    const pending = openPrs.find((p) => String(p.title ?? '').startsWith(RUN_TITLE));
    if (pending) {
      return {
        run: false,
        reason: `PR #${pending.number} is this pass's previous round, still open — comments wait for its review rather than stack a second sweep on it`,
      };
    }

    const commits = signals.commits;
    if (!commits?.substantiveChange) {
      return { run: false, reason: 'no substantive commit in the window — nothing moved for a comment to have drifted from' };
    }
    const touched = commits.touchedPaths ?? [];
    if (!touched.length) {
      return { run: false, reason: 'the window\'s commits name no changed path — nothing to read' };
    }

    // A window can carry more files than one session should read as comments. Name
    // the cap and what it dropped rather than hand over a silently truncated list
    // that reads as the whole window.
    const scope = touched.slice(0, MAX_FILES);
    const dropped = touched.length - scope.length;
    return {
      run: true,
      reason: `${touched.length} path(s) changed in the window`,
      context: [
        `Read the comments in exactly these files, and no others: ${scope.join(', ')}.`,
        ...(dropped ? [`${dropped} further path(s) changed in the window and are NOT in scope this round — say so in the wrap-up so the next round is not read as a full sweep.`] : []),
        'A file whose comments are already right yields no edit — that is the common outcome and a good one.',
      ],
    };
  },
};

