32	const titleOf = (item) => (item.title ?? '').trim();
33	// An item somebody is executing — the executor holds it, or the agent it handed to
34	// does. Decoded, never a literal label test: the item may wear any engine's spelling.
35	const running = (item) => isStatus(item, STATUS_RUNNING_EXECUTOR) || isStatus(item, STATUS_RUNNING_AGENT);
36	// WHICH TASK AN ITEM NAMES. A filed `[claudinite-work]` item says so in its title;
37	// a marked issue (DESIGN §16.1) keeps its own human title and names its task in the
38	// machine block's first line, so the id comes from the task whose worker path that
39	// is. `pathTo` is that lookup, injected because only the run holds the task set.
40	const taskIdOf = (item, pathTo = () => null) => {
41	  const p = parseWorkItemTitle(item.title);
42	  if (p) return `${p.pack}/${p.task}`;
43	  return pathTo(parseWorkItemBody(item.body).taskPath) ?? null;
44	};
