90	// The claim comment carries WHO and WHEN — the executor id and its run URL —
91	// because executor identity is an unbounded set and must never become a label
92	// (DESIGN §4).
93	export const claimComment = ({ executor, runUrl, at }) =>
94	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
95	
96	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
97	// each an implicit assumption made explicit:
98	//
99	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
100	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
101	//    comment ids are server-assigned and strictly increasing — a total order the
102	//    protocol gets for free. Nothing here compares runner clocks.
103	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
104	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
105	//    and revert leaves one), and arbitrating over all of them makes a dead claim
106	//    outrank every future live claimant — the item then livelocks through reclaim
107	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
108	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
109	//    owner; it can only leave an item with no state label, which the janitor
110	//    repairs.
111	export function claimWinner(comments = []) {
112	  const sorted = [...comments].sort((a, b) => a.id - b.id);
113	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
114	  const claims = sorted
115	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
116	    .filter((c) => !boundary || c.id > boundary.id);
117	  return claims[0] ?? null;
118	}
119	
120	// After WINNING a claim, re-verify the pick filters against live state (F15). The
121	// filters read possibly-stale state, so two executors can pass them simultaneously
122	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
123	// an upstream and its dependent. The per-item lease cannot see that: it protects
124	// one item, not one title. If a conflicting item now holds an EARLIER claim
125	// (comment id — the same arbiter the lease trusts), this executor reverts its own
126	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
127	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null, pathTo = () => null } = {}) {
128	  const idOf = (i) => taskIdOf(i, pathTo);
129	  const standing = (i) => isStandingItem(i, frequencyOf(idOf(i)));
130	  const upstreams = standing(item) ? taskAfter(idOf(item)) : [];
131	  return others.some((o) => {
132	    if (o.number === item.number) return false;
133	    if (!running(o)) return false;
134	    const conflicting = titleOf(o) === titleOf(item)
135	      || (upstreams.includes(idOf(o)) && standing(o));
136	    return conflicting && o.claimId != null && o.claimId < myClaimId;
137	  });
138	}
